(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-958":{scenario:{company:"Mekong Orchard Export",supervisor:{name:"Mạc Quang Thiện",role:{vi:"Trưởng phòng Xuất khẩu",en:"Export Manager"}},ref_code:"KD-5523",title:{vi:"Đúng mã vùng trồng. Đúng khối lượng. Giữ thị trường cho cả vùng.",en:"Right orchard code. Right weight. Keep the market open."},brief:{vi:"Bạn chuẩn bị hồ sơ đăng ký kiểm dịch KD-5523 cho một container thanh long tươi xuất khẩu. Phiếu đóng gói: 1560 thùng, mỗi thùng 5 kg tịnh; trong đó 312 thùng thu từ vườn có mã số vùng trồng đã bị tạm dừng sau lần phát hiện sinh vật gây hại. Phòng xuất khẩu đã đối chiếu danh sách mã số vùng trồng còn hiệu lực. Sửa mã số vùng trồng và khối lượng tịnh khai báo, rồi lập báo cáo có căn cứ.",en:"You are preparing phytosanitary inspection request KD-5523 for one container of fresh dragon fruit for export. Packing list: 1560 cartons, 5 kg net each; 312 of them came from an orchard whose production unit code was suspended after a pest interception. The export team has checked the list of valid production unit codes. Correct the production unit code and the declared net weight, then write an evidence-based report."},reference_title:{vi:"Danh sách mã số vùng trồng hiệu lực & phiếu đóng gói · KD-5523",en:"Valid production unit code list & packing list · KD-5523"},fields:[{id:"PUC_CODE",label:{vi:"Mã số vùng trồng khai báo",en:"Declared production unit code"},initial:"PUC-LA-0142",expected:"PUC-LA-0417",choices:["PUC-LA-0142","PUC-LA-0417","PUC-TG-0088"],reference:"Danh sách mã số vùng trồng còn hiệu lực",hint:{vi:"Chỉ khai mã số đang còn hiệu lực trong danh sách đã phê duyệt; mã của vườn bị tạm dừng không được sử dụng.",en:"Declare only a code that is valid on the approved list; a suspended orchard's code cannot be used."}},{id:"NET_KG",label:{vi:"Khối lượng tịnh khai báo (kg)",en:"Declared net weight (kg)"},initial:"7800",expected:"6240",reference:"Phiếu đóng gói theo vườn",ref_value:{vi:"1560 thùng x 5 kg tịnh; 312 thùng từ vườn có mã bị tạm dừng",en:"1560 cartons x 5 kg net; 312 cartons from the suspended orchard"},hint:{vi:"Thùng từ vườn có mã bị tạm dừng phải tách khỏi lô xuất, không được tính vào khối lượng khai báo.",en:"Cartons from the suspended orchard must be removed from the export lot and excluded from the declared weight."}}],sop32:{vi:"Chỉ khai các thùng từ vùng trồng có mã số còn hiệu lực; khối lượng tịnh = số thùng hợp lệ x khối lượng tịnh mỗi thùng; thùng không hợp lệ tách lô và lập biên bản.",en:"Declare only cartons from production units with a valid code; net weight = valid cartons x net weight per carton; invalid cartons are separated and recorded."},context:{label:"HỒ SƠ KIỂM DỊCH NHÁP / KD-5523",metrics:[{label:{vi:"Tổng số thùng",en:"Total cartons"},value:"1560"},{label:{vi:"Khối lượng tịnh mỗi thùng",en:"Net weight per carton"},value:"5 kg"},{label:{vi:"Thùng từ mã bị tạm dừng",en:"Cartons from suspended code"},value:"312"}]},crisis:{vi:"Giám đốc kinh doanh nhắn: “Cứ để 312 thùng vườn B chung container, dán nhãn mã PUC-LA-0417 cho đủ hàng. Đối tác đang chờ, lần trước có ai mở kiểm tra từng thùng đâu.”",en:"The sales director messages you: “Keep orchard B's 312 cartons in the container and label them PUC-LA-0417 to fill the order. The buyer is waiting and nobody opened every carton last time.”"},options:{safe:{vi:"Từ chối dán nhãn sai mã số vùng trồng; tách 312 thùng để tiêu thụ nội địa, khai đúng 6240 kg, báo trưởng phòng xuất khẩu, thông báo đối tác và đề xuất bổ sung hàng từ vườn có mã hợp lệ.",en:"Refuse to mislabel the production unit code; separate the 312 cartons for the domestic market, declare 6240 kg, inform the export manager, notify the buyer and propose topping up from a valid orchard."},shortcut:{vi:"Dán nhãn mã PUC-LA-0417 cho cả 1560 thùng để giao đủ container đúng hẹn.",en:"Label all 1560 cartons PUC-LA-0417 to ship a full container on time."},wait:{vi:"Chưa nộp hồ sơ, chờ giám đốc kinh doanh tự quyết định việc ghép hàng.",en:"Hold the filing and wait for the sales director to decide on mixing the lots."}},questions:{vi:["Vì sao khai mã PUC-LA-0417 và khối lượng tịnh 6240 kg? Chứng từ nào chứng minh?","Nêu rủi ro cho doanh nghiệp và cả vùng trồng nếu dán sai mã số, và cách bạn xử lý với đối tác nhập khẩu."],en:["Why did you declare PUC-LA-0417 and a net weight of 6240 kg? Which documents prove it?","Describe the risks to the company and the whole growing area from mislabelling the code, and how you handle the importer."]},hints:{vi:["Đối chiếu từng mã trên phiếu đóng gói với danh sách mã số vùng trồng còn hiệu lực.","Trừ số thùng của vườn bị tạm dừng trước khi nhân khối lượng tịnh mỗi thùng theo SOP mục 3.2.","Đọc lại SOP mục 4.2: gian lận mã số vùng trồng có thể khiến cả thị trường bị đình chỉ; phải báo cáo."],en:["Check each code on the packing list against the list of valid production unit codes.","Subtract the suspended orchard's cartons before multiplying by net weight per carton as in SOP 3.2.","Re-read SOP 4.2: code fraud can get the whole market suspended; it must be escalated."]}},learning:{summary:{vi:"Chuyên viên xuất khẩu nông sản và kiểm dịch chuẩn bị, kiểm soát hồ sơ để rau quả, nông sản đáp ứng yêu cầu kiểm dịch thực vật, an toàn thực phẩm và truy xuất của nước nhập khẩu: mã số vùng trồng, cơ sở đóng gói, xử lý kiểm dịch, chứng thư kiểm dịch và dư lượng thuốc bảo vệ thực vật. Nghề giữ cửa thị trường cho cả doanh nghiệp và vùng trồng nên đòi hỏi chính xác, hiểu quy định quốc tế và trung thực tuyệt đối.",en:"An agri-food export and phytosanitary officer prepares and controls the files that let fruit and produce meet the importing country's plant health, food safety and traceability requirements: production unit codes, packing house codes, quarantine treatments, phytosanitary certificates and pesticide residues. The role keeps markets open for the company and the whole growing area, so it demands precision, knowledge of international rules and complete honesty."},responsibilities:{vi:["Theo dõi yêu cầu kiểm dịch và an toàn thực phẩm của từng thị trường nhập khẩu.","Quản lý mã số vùng trồng, cơ sở đóng gói và hồ sơ truy xuất của từng lô hàng.","Đăng ký kiểm dịch, phối hợp xử lý kiểm dịch (chiếu xạ, hơi nước nóng, xử lý lạnh) khi được yêu cầu.","Kiểm tra nội bộ lô hàng: sinh vật gây hại, quy cách đóng gói, nhãn mác, vật liệu gỗ.","Xử lý cảnh báo, vi phạm từ nước nhập khẩu và lập kế hoạch khắc phục."],en:["Track the plant health and food safety requirements of each importing market.","Manage production unit codes, packing house codes and traceability files for every lot.","Request inspections and arrange quarantine treatments (irradiation, vapour heat, cold) when required.","Pre-inspect lots for pests, packing standards, labels and wood packaging.","Handle notifications and violations from importing countries and plan corrective actions."]},competencies:[{name:{vi:"Hiểu quy định kiểm dịch quốc tế",en:"International phytosanitary rules"},desc:{vi:"Nắm tiêu chuẩn IPPC, hiệp định SPS và yêu cầu riêng của từng nước nhập khẩu.",en:"Know IPPC standards, the SPS Agreement and each importer's specific requirements."}},{name:{vi:"Quản lý hồ sơ & truy xuất",en:"Documentation & traceability"},desc:{vi:"Liên kết từng thùng hàng với vườn, cơ sở đóng gói và nhật ký canh tác.",en:"Link every carton to its orchard, packing house and crop records."}},{name:{vi:"Kiểm soát chất lượng lô hàng",en:"Lot quality control"},desc:{vi:"Kiểm tra sinh vật gây hại, dư lượng, quy cách và nhãn trước khi đăng ký kiểm dịch.",en:"Check pests, residues, packing and labels before requesting inspection."}},{name:{vi:"Phối hợp chuỗi cung ứng",en:"Supply chain coordination"},desc:{vi:"Làm việc với vườn, cơ sở đóng gói, đơn vị xử lý, hãng tàu và cơ quan kiểm dịch.",en:"Work with orchards, packing houses, treatment facilities, carriers and the quarantine authority."}},{name:{vi:"Liêm chính thương mại",en:"Trade integrity"},desc:{vi:"Từ chối gian lận mã số, nhãn mác dù chịu áp lực doanh số và báo cáo kịp thời.",en:"Refuse code and label fraud under sales pressure and escalate promptly."}}],knowledge:{vi:["Công ước Bảo vệ thực vật quốc tế (IPPC) và tiêu chuẩn ISPM, gồm ISPM 12 về chứng thư kiểm dịch, ISPM 15 về vật liệu đóng gói bằng gỗ.","Hiệp định về các biện pháp vệ sinh và kiểm dịch động thực vật (SPS) của WTO.","Luật Bảo vệ và kiểm dịch thực vật số 41/2013/QH13 và quy định về mã số vùng trồng, cơ sở đóng gói.","Giới hạn dư lượng tối đa (MRL) của Codex và của từng thị trường nhập khẩu.","Các phương pháp xử lý kiểm dịch: chiếu xạ, hơi nước nóng, xử lý lạnh, xông hơi."],en:["International Plant Protection Convention (IPPC) and ISPM standards, including ISPM 12 on phytosanitary certificates and ISPM 15 on wood packaging.","The WTO Agreement on Sanitary and Phytosanitary Measures (SPS).","Law on Plant Protection and Quarantine No. 41/2013/QH13 and rules on production unit and packing house codes.","Codex and importing-country maximum residue limits (MRL).","Quarantine treatments: irradiation, vapour heat, cold treatment and fumigation."]},tools:["Cổng một cửa quốc gia (khai báo điện tử)","Cơ sở dữ liệu mã số vùng trồng","Kính lúp & bàn soi sinh vật gây hại","Phần mềm truy xuất lô hàng","Bảng tính phiếu đóng gói"],kpis:{vi:["Số lô bị nước nhập khẩu cảnh báo hoặc trả về (mục tiêu bằng 0).","Tỷ lệ hồ sơ kiểm dịch đúng ngay lần đầu.","Thời gian từ đóng gói đến khi có chứng thư kiểm dịch.","Tỷ lệ lô hàng truy xuất đầy đủ đến vườn trồng."],en:["Lots notified or rejected by importing countries (target zero).","Right-first-time phytosanitary filing rate.","Time from packing to phytosanitary certificate.","Share of lots fully traceable to the orchard."]},day:[{time:"07:30",vi:"Kiểm tra cập nhật danh sách mã số vùng trồng và cảnh báo từ thị trường.",en:"Check updates to the production unit code list and market notifications."},{time:"09:00",vi:"Có mặt cơ sở đóng gói, kiểm tra ngẫu nhiên thùng hàng, nhãn và pallet gỗ.",en:"At the packing house, spot-check cartons, labels and wooden pallets."},{time:"11:00",vi:"Đăng ký kiểm dịch và đặt lịch xử lý kiểm dịch cho lô hàng.",en:"File the inspection request and book the quarantine treatment slot."},{time:"14:00",vi:"Đối chiếu phiếu đóng gói theo từng vườn với mã số còn hiệu lực.",en:"Match the packing list by orchard against valid codes."},{time:"16:30",vi:"Cập nhật hồ sơ truy xuất và gửi bộ chứng từ cho khách hàng nhập khẩu.",en:"Update traceability files and send the document set to the importer."}],mistakes:{vi:["Dùng mã số vùng trồng của mùa trước mà không kiểm tra tình trạng hiệu lực.","Ghép hàng từ vườn không có mã hợp lệ vào lô xuất cho đủ container.","Dùng pallet gỗ chưa xử lý, không có dấu ISPM 15."],en:["Reusing last season's production unit code without checking it is still valid.","Mixing produce from orchards without a valid code into the export lot to fill a container.","Using untreated wooden pallets without the ISPM 15 mark."]},career:[{vi:"Nhân viên chứng từ xuất khẩu nông sản",en:"Agri-food export documentation assistant"},{vi:"Chuyên viên xuất khẩu & kiểm dịch",en:"Export & phytosanitary officer"},{vi:"Trưởng phòng xuất khẩu",en:"Export manager"},{vi:"Giám đốc phát triển thị trường nông sản",en:"Agri-food market development director"}],glossary:[{term:"PUC",vi:"Mã số vùng trồng: mã định danh vùng sản xuất được cấp để truy xuất và giám sát sinh vật gây hại.",en:"Production unit code identifying a growing area for traceability and pest surveillance."},{term:"Phytosanitary certificate",vi:"Chứng thư kiểm dịch thực vật do cơ quan có thẩm quyền nước xuất khẩu cấp cho lô hàng.",en:"Plant health certificate issued for a consignment by the exporting country's authority."},{term:"ISPM 15",vi:"Tiêu chuẩn quốc tế về xử lý và đánh dấu vật liệu đóng gói bằng gỗ trong thương mại.",en:"International standard for treating and marking wood packaging material in trade."},{term:"SPS",vi:"Hiệp định WTO về biện pháp vệ sinh an toàn thực phẩm và kiểm dịch động thực vật.",en:"WTO agreement on sanitary and phytosanitary measures."},{term:"MRL",vi:"Giới hạn dư lượng tối đa của thuốc bảo vệ thực vật được phép trong nông sản.",en:"Maximum residue limit of a pesticide permitted in produce."}],quiz:[{q:{vi:"ISPM 15 quy định về vấn đề gì?",en:"What does ISPM 15 cover?"},options:{vi:["Dư lượng thuốc trên quả","Xử lý và đánh dấu vật liệu đóng gói bằng gỗ","Nhãn dinh dưỡng","Quy cách thùng carton"],en:["Pesticide residues on fruit","Treatment and marking of wood packaging","Nutrition labelling","Carton specifications"]},answer:1,explain:{vi:"ISPM 15 yêu cầu vật liệu gỗ đóng gói được xử lý nhiệt hoặc xông hơi và đóng dấu theo mẫu quốc tế.",en:"ISPM 15 requires wood packaging to be heat-treated or fumigated and marked with the international mark."}},{q:{vi:"Lô 2000 thùng x 4 kg tịnh, trong đó 250 thùng từ vườn có mã bị tạm dừng. Khối lượng tịnh được khai là bao nhiêu?",en:"A lot of 2000 cartons x 4 kg net includes 250 cartons from a suspended orchard. What net weight may be declared?"},options:{vi:["8000 kg","1000 kg","7000 kg","7750 kg"],en:["8000 kg","1000 kg","7000 kg","7750 kg"]},answer:2,explain:{vi:"Số thùng hợp lệ = 2000 - 250 = 1750; khối lượng tịnh = 1750 x 4 = 7000 kg.",en:"Valid cartons = 2000 - 250 = 1750; net weight = 1750 x 4 = 7000 kg."}},{q:{vi:"Kinh doanh muốn dán mã vùng trồng hợp lệ lên hàng từ vườn bị tạm dừng. Bạn làm gì?",en:"Sales wants to put a valid code on produce from a suspended orchard. What do you do?"},options:{vi:["Đồng ý vì cùng tỉnh","Dán mã trên một phần thùng","Hỏi đối tác có chấp nhận không","Từ chối, tách lô, báo trưởng phòng và khai đúng"],en:["Agree since it is the same province","Label only some cartons","Ask the buyer if they mind","Refuse, separate the lot, inform the manager and declare correctly"]},answer:3,explain:{vi:"Gian lận mã số vùng trồng có thể khiến nước nhập khẩu đình chỉ cả vùng hoặc cả ngành hàng.",en:"Code fraud can lead the importing country to suspend the whole area or product sector."}},{q:{vi:"Mục đích chính của mã số vùng trồng là gì?",en:"What is the main purpose of a production unit code?"},options:{vi:["Truy xuất nguồn gốc và giám sát sinh vật gây hại tới từng vùng sản xuất","Tính thuế xuất khẩu","Quảng bá thương hiệu","Xác định giá bán"],en:["Trace origin and monitor pests down to each growing area","Calculate export tax","Promote a brand","Set the selling price"]},answer:0,explain:{vi:"Mã số vùng trồng giúp cơ quan kiểm dịch hai nước truy ngược lô hàng và khoanh vùng khi phát hiện sinh vật gây hại.",en:"The code lets both countries' authorities trace a lot back and contain problems when pests are found."}}],tools_en:["Vietnam National Single Window (VNSW)","Growing area code database","Magnifier & pest inspection table","Shipment traceability software","Packing list spreadsheet"]}}})})(window.KKR);
